import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <cstdint>

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    long K,
    bool use_vec)
{
    const long row = blockIdx.x;
    const float* __restrict__ Arow = A + row * K;

    float acc = 0.0f;

    if (use_vec) {
        const long G = K >> 2;
        const float4* __restrict__ A4 = reinterpret_cast<const float4*>(Arow);
        const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
        #pragma unroll 4
        for (long g = threadIdx.x; g < G; g += blockDim.x) {
            const float4 a = A4[g];
            const float4 b = B4[g];
            acc += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
    } else {
        for (long k = threadIdx.x; k < K; k += blockDim.x) {
            acc += Arow[k] * B[k];
        }
    }

    __shared__ float warp_sums[32];
    const unsigned int mask = 0xffffffffu;
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;

    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(mask, acc, offset);
    }

    if (lane == 0) {
        warp_sums[warp] = acc;
    }
    __syncthreads();

    if (warp == 0) {
        const int num_warps = (blockDim.x + 31) >> 5;
        float sum = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
        }
        if (lane == 0) {
            C[row] = sum;
        }
    }
}

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32,
                "A and B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "A must have shape (M, K)");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();

    const int64_t M = Ac.size(0);
    const int64_t K = Ac.size(1);

    auto C = torch::empty({M, 1}, Ac.options());
    if (M == 0) {
        return C;
    }

    c10::cuda::CUDAGuard device_guard(Ac.device());

    const float* Aptr = Ac.data_ptr<float>();
    const float* Bptr = Bc.data_ptr<float>();
    float* Cptr = C.data_ptr<float>();

    const bool use_vec =
        ((K & 3) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(Aptr) & 15) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(Bptr) & 15) == 0);

    const dim3 block(256);
    const dim3 grid(static_cast<unsigned int>(M));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();

    matvec_kernel<<<grid, block, 0, stream>>>(Aptr, Bptr, Cptr, K, use_vec);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));

    return C;
}
"""

_matvec_ext = load_inline(
    name="matvec_fused_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matvec_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matvec_ext.matvec_cuda(A, B)

